patterns.template:
SELECT COUNT(*) AS n, AVG(`Shipping Fee`) AS avg_fee, MAX(`Shipping Fee`) AS max_fee
FROM orders
WHERE `Ship Country/Region` = 'USA';

SELECT o.`Order ID`, c.`Company`
FROM orders AS o
JOIN customers AS c ON c.ID = o.`Customer ID`;

SELECT *
FROM products
WHERE `List Price` > (SELECT AVG(`List Price`) FROM products);

SELECT c.*
FROM customers AS c
WHERE EXISTS (SELECT 1 FROM orders AS o WHERE o.`Customer ID` = c.ID);

SELECT c.*
FROM customers AS c
WHERE NOT EXISTS (SELECT 1 FROM orders AS o WHERE o.`Customer ID` = c.ID);

SELECT *
FROM products
WHERE ID IN (SELECT `Product ID` FROM `order details`);

SELECT p.*
FROM products AS p
WHERE p.`List Price` > (SELECT AVG(q.`List Price`) FROM products AS q WHERE q.Category = p.Category);

-- non-sargable
SELECT * FROM orders WHERE YEAR(`Order Date`) = 2006;
-- sargable + only needed columns
SELECT `Order ID`, `Customer ID`, `Order Date`
FROM orders
WHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01';
-- and CREATE INDEX idx_orders_date ON orders (`Order Date`);

SELECT COUNT(*) AS all_rows, COUNT(`Payment Type`) AS with_type,
       SUM(`Payment Type` IS NULL) AS missing
FROM orders;

SELECT `Product Name`, ROUND((`List Price` - `Standard Cost`) / `Standard Cost`, 4) AS `Profit Margin`
FROM products
WHERE (`List Price` - `Standard Cost`) / `Standard Cost` >= 0.5;

SELECT `Company` FROM customers
UNION
SELECT `Company` FROM suppliers;
